SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Subscription Charge', '{"description": "A billing event for a subscription. GAME_SALES.SUBSCRIPTION_CHARGES (SUBSCRIBER_ID = customer, PLAN_ID, billing period, GROSS_REVENUE)."}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Revenue Type', '{"description": "What kind of thing was sold. GAME_SALES.REVENUE_TYPES (CATEGORY_ID, MONETIZATION_TYPE = what was sold, CATEGORY_GROUP = DIGITAL / HARDWARE / SUBSCRIPTION)."}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Digital Gross Revenue', '{"description": "Gross value of all digital store sales, before platform commission. Grain: one row per purchase in DIGITAL_PRODUCT_TRANSACTIONS. Include every row: do NOT filter TITLE_ID IS NOT NULL; about 1 in 10 rows has no TITLE_ID but still belongs to a game through DIGITAL_PRODUCT_ID -> DIGITAL_PRODUCTS.TITLE_ID. Region: join PLAYER_ID to CUSTOMER_ACCOUNTS (SIE Region Code). Additive across games, products, customers and time. Includes physical editions sold as BASE_GAME_PHYSICAL (see Revenue Type Code).", "formula": "SUM(GROSS_REVENUE) FROM ONTOLOGY_DEMO.GAME_SALES.DIGITAL_PRODUCT_TRANSACTIONS"}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Net Publisher Revenue', '{"description": "Net digital revenue the Publisher keeps after the store commission. Grain: one row per digital purchase. The column is named NET_DEVELOPER_REVENUE but it is the PUBLISHER share, not the Developer''s (developers are studios owned by the publisher and get no separate share). Do not report gross for this question. Same row rules as Digital Gross Revenue (keep rows with NULL TITLE_ID). Additive.", "formula": "SUM(NET_DEVELOPER_REVENUE) FROM ONTOLOGY_DEMO.GAME_SALES.DIGITAL_PRODUCT_TRANSACTIONS"}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Platform Commission Revenue', '{"description": "The store''s cut of digital sales: gross minus the publisher share, per purchase (PLATFORM_COMMISSION_PCT is the rate). Grain: one row per digital purchase. This is the only part of digital sales the platform keeps. Additive.", "formula": "SUM(GROSS_REVENUE - NET_DEVELOPER_REVENUE) FROM ONTOLOGY_DEMO.GAME_SALES.DIGITAL_PRODUCT_TRANSACTIONS"}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Hardware Revenue', '{"description": "Gross sales of consoles and peripherals. Grain: one row per hardware purchase in HARDWARE_SALES_TRANSACTIONS (BUYER_ID = customer, linked to HARDWARE_PRODUCTS). Region: filter this table''s own REGION column, which uses Sales Region Codes NA/EU/JP/ASIA/LATAM; the SIE codes (SIEA...) are for customers and match nothing here. Platform keeps all of it. Additive.", "formula": "SUM(GROSS_REVENUE) FROM ONTOLOGY_DEMO.GAME_SALES.HARDWARE_SALES_TRANSACTIONS"}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Subscription Revenue', '{"description": "Gross PlayStation Plus billing. Grain: one row per subscription charge in SUBSCRIPTION_CHARGES (SUBSCRIBER_ID = customer, PLAN_ID = Subscription Plan, billing period dates). Gross; no commission is deducted. No region column: for region join SUBSCRIBER_ID to CUSTOMER_ACCOUNTS (SIE Region Code). Platform keeps all of it. Additive.", "formula": "SUM(GROSS_REVENUE) FROM ONTOLOGY_DEMO.GAME_SALES.SUBSCRIPTION_CHARGES"}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Total Platform Revenue', '{"description": "What the platform keeps business-wide = Hardware Revenue + Platform Commission Revenue + Subscription Revenue. Digital contributes ONLY the commission; the publisher share is not platform revenue. Pitfall: summing every GROSS_REVENUE column (including full digital gross) overstates it. Additive across the three parts.", "formula": "Hardware Revenue + Platform Commission Revenue + Subscription Revenue"}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Active Customer Count', '{"description": "Customers whose account is active (Account Status ''A''); excludes S (suspended) and C (closed). Grain: one row per customer in CUSTOMER_ACCOUNTS. STATUS here means account status, not game or listing status. Region: REGION uses SIE Region Codes (North America = ''SIEA'', not ''NA''). Count, additive across regions.", "formula": "COUNT(*) FROM ONTOLOGY_DEMO.GAME_SALES.CUSTOMER_ACCOUNTS WHERE STATUS = ''A''"}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Battle Pass Sales Revenue', '{"description": "Gross revenue from battle passes actually SOLD: digital purchases whose product''s Revenue Type Code is BATTLE_PASS. Not the same as games tagged with a battle_pass business model in MONETIZATION_TYPES, which is a tag with no money attached. Grain: one row per digital purchase. Additive.", "formula": "SUM(t.GROSS_REVENUE) FROM DIGITAL_PRODUCT_TRANSACTIONS t JOIN DIGITAL_PRODUCTS p USING (DIGITAL_PRODUCT_ID) JOIN REVENUE_TYPES r ON r.CATEGORY_ID = p.CATEGORY_ID WHERE r.MONETIZATION_TYPE = ''BATTLE_PASS''"}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Currently Exclusive Game Count', '{"description": "Game-platform pairs exclusive today. Grain: one row per game and platform in Sales GAME_PLATFORMS. IS_EXCLUSIVE is text ''Y''/''N'' in Sales (BOOLEAN in Catalog), so compare to ''Y''. Timed exclusives count only while EXCLUSIVE_END is today or later. Counts pairs, not games.", "formula": "COUNT(*) FROM ONTOLOGY_DEMO.GAME_SALES.GAME_PLATFORMS WHERE IS_EXCLUSIVE = ''Y'' AND (EXCLUSIVITY_TYPE = ''PERMANENT'' OR (EXCLUSIVITY_TYPE = ''TIMED'' AND EXCLUSIVE_END >= CURRENT_DATE))"}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Game Revenue', '{"description": "Revenue per catalog Game. Title per row = COALESCE(t.TITLE_ID, p.TITLE_ID); resolve each title to a Game via TITLES.CATALOG_GAME_ID, then TITLE_CODE_XREF.CATALOG_GAME_ID, then name + release year (Game Identity Match Rule; compare names with COLLATE(..., ''en-ci-ai''), not LOWER()). Grain: one row per digital purchase, grouped to a catalog GAME_ID. Gross, additive across games; summed over all games it equals Digital Gross Revenue. Pitfall: joining on TITLES.CATALOG_GAME_ID alone drops every title that only the crosswalk or the name + year route can resolve. Find a game by its catalog name or a Sales alias (see Game).", "formula": "SUM(t.GROSS_REVENUE) FROM DIGITAL_PRODUCT_TRANSACTIONS t JOIN DIGITAL_PRODUCTS p USING (DIGITAL_PRODUCT_ID) GROUP BY resolved catalog GAME_ID"}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Developer Revenue', '{"description": "Game Revenue per Developer: resolve each sale to a catalog Game first (Game Identity Match Rule), then group by GAMES.DEVELOPER_NAME. Developer has no table of its own; Sales TITLES.STUDIO is the same studio spelled with spaces. Gross, additive across developers.", "formula": "Game Revenue GROUP BY GAMES.DEVELOPER_NAME"}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Franchise Revenue', '{"description": "Game Revenue per Franchise: resolve each sale to a catalog Game first (Game Identity Match Rule), then group by franchise name (GAMES.FRANCHISE_NAME or GAME_FRANCHISES.FRANCHISE_NAME). Franchise has no table of its own. Gross, additive across franchises.", "formula": "Game Revenue GROUP BY GAME_FRANCHISES.FRANCHISE_NAME"}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Active Catalog Game Count', '{"description": "Catalog games that are not delisted (Game Lifecycle Status <> ''DELISTED''). Grain: one row per game in GAME_CATALOG.GAMES. Use GAMES.STATUS, not the account or listing STATUS columns. Count.", "formula": "COUNT(*) FROM ONTOLOGY_DEMO.GAME_CATALOG.GAMES WHERE STATUS <> ''DELISTED''"}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Genre Match Score', '{"description": "Share of a genre rule''s conditions a game meets. A game is a MEMBER of a genre only when MATCH_STATUS = ''FULL'' PARTIAL is not membership. Grain: one row per game and genre. Not additive.", "formula": "MET_CONDITIONS / TOTAL_CONDITIONS FROM ONTOLOGY_DEMO.GAME_CATALOG.GAME_GENRE_CLASSIFICATION"}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Genre Revenue', '{"description": "Game Revenue per Genre. Resolve each sale to a catalog Game first (Game Identity Match Rule: all three routes, with the name route compared via COLLATE(..., ''en-ci-ai'') so accents are ignored), then join the game to GENRE_ROLLUP (VW_GAME_GENRE_ROLLUP) on GAME_ID and group by ROLLUP_GENRE, so a parent genre includes every descendant genre. Apply the Genre Roll-up Rule (RPG also includes ActionRPG and Soulslike games). Each game counts once per genre and its full revenue goes to every genre it belongs to, so genre totals overlap and are NOT additive: never sum them to get total revenue. ''Which genre'' means top-level genres (ROLLUP_DEPTH = 1) unless subgenres are asked for. Gross.", "formula": "Game Revenue JOIN VW_GAME_GENRE_ROLLUP USING (GAME_ID) GROUP BY ROLLUP_GENRE"}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Weighted Overlap', '{"description": "Similarity between two games (GAME_SIMILARITY_SCORES.WEIGHTED_OVERLAP). Cannibalization candidates: same Publisher and >= 0.3. Not additive.", "formula": "SUM(dimension overlap * SIMILARITY_WEIGHTS.WEIGHT)"}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Catalog Game ID', '{"description": "Catalog key of a Game: GAME_CATALOG.GAMES.GAME_ID. Also stored as GAME_SALES.TITLES.CATALOG_GAME_ID (NULL for some titles) and GAME_SALES.TITLE_CODE_XREF.CATALOG_GAME_ID."}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Game Identity Match Rule', '{"description": "Policy for resolving a Sales title to a catalog Game, in order: (1) strong: TITLES.CATALOG_GAME_ID; (2) medium: TITLE_CODE_XREF.CATALOG_GAME_ID for the title; (3) weak: same name ignoring case and accents AND same release year, exactly: COLLATE(TITLES.TITLE_NAME, ''en-ci-ai'') = COLLATE(GAMES.GAME_NAME, ''en-ci-ai'') AND LEFT(TITLES.RELEASE_DATE, 4) = TO_CHAR(YEAR(GAMES.RELEASE_DATE)) (TITLES.RELEASE_DATE is text YYYYMMDD and may be the JP date). LOWER() or TRIM() alone do NOT remove accents, so a plain LOWER(name) comparison misses titles spelled without accents in Sales. Apply all three routes; skipping (2) and (3) leaves titles unmatched and undercounts revenue."}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Sales Title ID', '{"description": "GAME_SALES.TITLES.TITLE_ID (5001-5090), a Sales-only key that does NOT equal GAME_ID. Used in DIGITAL_PRODUCTS, Sales GAME_PLATFORMS, Sales GAME_MONETIZATION, DIGITAL_PRODUCT_TRANSACTIONS (NULL for every 10th row) and the revenue views."}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Title Code', '{"description": "GAME_SALES.TITLE_CODE_XREF.TITLE_CODE, the PlayStation Store code per game and platform. Prefix: PPSA = PS5, CUSA = PS4, NPUA = PS3, PCSA = PS Vita, SLUS = PS2. PC and Switch releases have no code. 100 codes; 12 games have more than one. TITLE_CODE_XREF.CATALOG_GAME_ID is the only route to the catalog for some titles."}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('SKU Code', '{"description": "GAME_SALES.DIGITAL_PRODUCTS.SKU_CODE, format <TitleCode>-C<CC><SS>: prefix = the game''s newest-generation Title Code, CC = REVENUE_TYPES.CATEGORY_ID (2 digits), SS = sequence within that title and category. Example PPSA97384-C0301 = Horizon Forbidden West, BASE_GAME_DIGITAL. Decode a SKU by matching its prefix to TITLE_CODE_XREF.TITLE_CODE and its CC to REVENUE_TYPES.CATEGORY_ID. Some products have no SKU (their game has no PlayStation code)."}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Game Lifecycle Status', '{"description": "GAMES.STATUS: RELEASED, REMASTERED, DELISTED (Concord). Different from Account Status and Listing Status, which share the column name STATUS."}');
