SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Monetization Model', '{"description": "MONETIZATION_TYPES.MONETIZATION_NAME (both systems; lower case): premium, free_to_play, microtransactions, battle_pass, loot_boxes, dlc, subscription, ads, season_pass. A business-model TAG on a game; nothing priced. LiveService is a business model, not a genre. Do not confuse with Revenue Type Code (same words, what was sold)."}');
