SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Exclusivity Flag', '{"description": "Sales GAME_PLATFORMS.IS_EXCLUSIVE is text ''Y''/''N'' (Catalog uses BOOLEAN). Currently exclusive = PERMANENT, or TIMED with EXCLUSIVE_END >= today."}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('POV Code', '{"description": "GAMES.POV: 1P = first person, 3P = third person."}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Genre Roll-up Rule', '{"description": "How to count or sum a genre including its subgenres. GAME_CATALOG.VW_GAME_GENRE_ROLLUP (logical table GENRE_ROLLUP) has one row per game per genre it belongs to: each FULL-matched genre plus all its ancestors in the PARENT_GENRE tree; ROLLUP_DEPTH 1 = top-level genre. (1) For a parent or top-level genre use GENRE_ROLLUP.ROLLUP_GENRE, never GENRE_CLASSIFICATION.GENRE (parents have no FULL rows of their own). (2) The tree is single-parent, so RPG members must be added by hand: RPG = games with ROLLUP_GENRE IN (''RPG'', ''ActionRPG'', ''Soulslike'', ''Roguelike''), counted with COUNT(DISTINCT GAME_ID). (3) A game counts once per genre and belongs to several genres, so per-genre counts and revenue overlap and are not additive. (4) ''Which genre'' ranks top-level genres (ROLLUP_DEPTH = 1, plus RPG per rule 2) unless subgenres are asked for."}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Genre Match Status', '{"description": "GAME_GENRE_CLASSIFICATION.MATCH_STATUS: FULL = member; PARTIAL, NONE, UNEVALUABLE = not a member."}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Genre Rule', '{"description": "GENRE_RULES is the executable source (used by SP_CLASSIFY_GAMES). RULE_DEFINITION syntax: hasX VALUE v (exact value), hasX SOME Category (any value in a GENRE_CATEGORY_MAP category), MIN/MAX (player count), NOT(...), INTERSECTION(...) = AND. PARENT_GENRE is single-parent BY DESIGN: ActionRPG and Soulslike sit under Action, so the strict tree alone finds no RPG members; the ontology links them to RPG. Disjoint pairs: FPS-TPS, MMO-LocalMultiplayer, Cozy-Horror, Artistic-Realistic, MMO-SinglePlayer. Genres held as values only (no node): DynamicAdventure, Survival, Explorative, FamiliarExploration, FantasyExploration, InteractiveMovie, Metroidvania, VisualNovel, Gore, Psychological, SurvivalHorror, Roguelike, Tactic, BattleRoyale, Match, Scrolling, DatingSim, DrivingSim, JobSim, Management, SandBox, Sport, Artistic, Educational, PuzzleGame, Cozy, Other, LiveService, MultiplayerAvailable, MMO, LocalMultiplayer, Genre (root)."}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Action', '{"description": "Genre. Top-level. Members = union of Shooter, Fighting, Platformer, Stealth, Survival, ActionRPG, DynamicAdventure and their subgenres. Membership: FULL match in GAME_GENRE_CLASSIFICATION; a parent''s members are the union of its descendants, queryable as GENRE_ROLLUP.ROLLUP_GENRE = ''Action'' (VW_GAME_GENRE_ROLLUP; see Genre Roll-up Rule). Source value GENRE_RULES.GENRE = ''Action''."}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Adventure', '{"description": "Genre. Top-level. Includes Explorative, InteractiveMovie, Metroidvania, VisualNovel. Membership: FULL match in GAME_GENRE_CLASSIFICATION; a parent''s members are the union of its descendants, queryable as GENRE_ROLLUP.ROLLUP_GENRE = ''Adventure'' (VW_GAME_GENRE_ROLLUP; see Genre Roll-up Rule). Source value GENRE_RULES.GENRE = ''Adventure''."}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('RPG', '{"description": "Genre. Top-level. Members = RPG + Roguelike + ActionRPG + Soulslike. ActionRPG and Soulslike sit under Action in GENRE_RULES, so ROLLUP_GENRE = ''RPG'' alone misses them; always use ROLLUP_GENRE IN (''RPG'', ''Roguelike'', ''ActionRPG'', ''Soulslike''). Count distinct games. Membership: FULL match in GAME_GENRE_CLASSIFICATION; a parent''s members are the union of its descendants, queryable as GENRE_ROLLUP.ROLLUP_GENRE = ''RPG'' (VW_GAME_GENRE_ROLLUP; see Genre Roll-up Rule). Source value GENRE_RULES.GENRE = ''RPG''."}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Horror', '{"description": "Genre. Top-level. Includes Gore, Psychological, SurvivalHorror. Disjoint with Cozy. Membership: FULL match in GAME_GENRE_CLASSIFICATION; a parent''s members are the union of its descendants, queryable as GENRE_ROLLUP.ROLLUP_GENRE = ''Horror'' (VW_GAME_GENRE_ROLLUP; see Genre Roll-up Rule). Source value GENRE_RULES.GENRE = ''Horror''."}');
SELECT SYSTEM$UPDATE_GLOSSARY_TERM('Simulator', '{"description": "Genre. Top-level. Includes DatingSim, DrivingSim, JobSim, Management, SandBox, Sport. Most sim rules are unmet by the data. Membership: FULL match in GAME_GENRE_CLASSIFICATION; a parent''s members are the union of its descendants, queryable as GENRE_ROLLUP.ROLLUP_GENRE = ''Simulator'' (VW_GAME_GENRE_ROLLUP; see Genre Roll-up Rule). Source value GENRE_RULES.GENRE = ''Simulator''."}');
